import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BZO4qERu.js";const c=JSON.parse('{"title":"Memoh 概览","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guides/overview.md","filePath":"zh/guides/overview.md","lastUpdated":1790952322000}'),l={name:"zh/guides/overview.md"};function h(i,e,s,n,m,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="memoh-概览" tabindex="-1">Memoh 概览 <a class="header-anchor" href="#memoh-概览" aria-label="Permalink to &quot;Memoh 概览&quot;">​</a></h1><p>Memoh 给每个 Bot 一台自己的云电脑：带真实文件系统和终端的工作区、可以看见和接管的桌面浏览器，以及跨会话的长期记忆。你的笔记本合上之后，它照常工作。</p><p>和 Bot 协作的方式就是给它发消息。在 Memoh 应用里聊，或者把它接到 Telegram、Slack、Discord、飞书、钉钉、企业微信、微信、QQ、LINE。无论从哪个入口进来，都是同一个 Bot 和同一份记忆。</p><p>上手只需要下载应用并登录 Memoh Cloud。托管模型（DeepSeek、Kimi、GPT、Claude 等）开箱即用；想换自己的 API Key 或模型服务，见 <a href="./quick-start.html#使用自己的模型-byok">BYOK</a>。</p><h2 id="memoh-有什么不同" tabindex="-1">Memoh 有什么不同 <a class="header-anchor" href="#memoh-有什么不同" aria-label="Permalink to &quot;Memoh 有什么不同&quot;">​</a></h2><ul><li><strong>一台真实的电脑，不是一次性沙盒。</strong> 写过的文件、装过的运行时都留在 <a href="./container.html">工作区</a> 里，周一建的东西周五还能接着用。</li><li><strong>一块你能看见的屏幕。</strong> Bot 在可视化桌面里操作真实浏览器；遇到登录或验证码，你<a href="./browser-computer-use.html">接管键鼠</a>处理完再交还给它。</li><li><strong>记得住。</strong> <a href="./memory.html">长期记忆</a> 跨会话、跨渠道生效，纠正过一次的偏好不用再说第二遍。</li><li><strong>你不在它也在跑。</strong> <a href="./schedule.html">定时任务</a> 按 cron 触发，结果发到你接入的渠道；到点检查、有变化才说话。</li><li><strong>自带你的编码智能体。</strong> 通过 <a href="./acp.html">ACP</a> 把 Claude Code、Codex 装进同一个工作区，用你自己的订阅。</li></ul><h2 id="一个-bot-负责一件事" tabindex="-1">一个 Bot 负责一件事 <a class="header-anchor" href="#一个-bot-负责一件事" aria-label="Permalink to &quot;一个 Bot 负责一件事&quot;">​</a></h2><p>每个 Bot 都有独立的工作区、记忆、渠道和权限边界，互不可见。工作确实分成不同角色时，就多建一个 Bot，而不是把一个越堆越重。谁能和 Bot 聊天、谁能读写它的文件、谁能执行命令，都在 <a href="./access.html">访问控制</a> 里按级别授予——需要哪级给哪级。</p><h2 id="第一个任务怎么交" tabindex="-1">第一个任务怎么交 <a class="header-anchor" href="#第一个任务怎么交" aria-label="Permalink to &quot;第一个任务怎么交&quot;">​</a></h2><p>挑一件你每周都在手动做的小事，说清楚结果、来源和边界：</p><blockquote><p>每周五 17:00，把我这一周发给你的链接和文件整理成一份周报，按主题分组、每条一句话，存进工作区并把摘要发到这个对话。只整理我发给你的内容，不要外发给任何人。</p></blockquote><p>Bot 会自己登记定时任务并按周交付。先从只读的活儿开始，检查过几次产出，再逐步放开写入和执行——更多现成搭配见 <a href="./use-cases.html">使用场景</a>。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>我关掉电脑，它还会跑吗？</strong></p><p>会。Bot 运行在云端工作区里，定时任务照常触发，渠道消息照常回复。</p><p><strong>可以建几个 Bot？</strong></p><p>取决于订阅计划。每个 Bot 都是独立的：自己的工作区、记忆和权限，删除一个不影响其他。</p><p><strong>我的文件放在哪？</strong></p><p>在该 Bot 的隔离容器工作区里（<code>/data</code>），跨会话保留，可在 <a href="./files.html">文件</a> 里随时查看和编辑。</p><p><strong>能用自己的模型吗？</strong></p><p>能。在模型服务商里加自己的 API Key（见 <a href="./quick-start.html#使用自己的模型-byok">BYOK</a>），编码智能体则在 Bot 的 <strong>Agent</strong> 标签页登录你自己的 Claude Code / Codex 订阅。</p><p><strong>订阅和计费的问题去哪问？</strong></p><p><a href="https://memoh.ai/help" target="_blank" rel="noreferrer">帮助中心</a>：套餐、credits、账号问题，以及联系 Memoh 团队的入口。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./quick-start.html">快速开始</a>——从装应用到接入聊天平台，十五分钟。</li><li><a href="./use-cases.html">使用场景</a>——组合多种功能解决实际问题的即用示例。</li><li><a href="./working-with-bots.html">Bot</a>——逐个标签页配置一个 Bot。</li><li><a href="./../integrations/channels/">渠道</a>——各聊天平台的接入方法。</li><li><a href="https://memoh.ai/help" target="_blank" rel="noreferrer">帮助中心</a>——订阅、账单与账号问题。</li></ul>',25)])])}const u=a(l,[["render",h]]);export{c as __pageData,u as default};
